/**
 * @summary Initializes tile
 *
 * @name base
 * @selector .slds-tile
 * @restrict article
 * @support dev-ready
 * @variant
 */
.slds-tile {

  + .slds-tile {
    margin-top: $spacing-x-small;
  }
}

/**
  * @selector .slds-tile__detail
  * @restrict .slds-tile div
  */
.slds-tile__detail {
  position: relative;
}

/**
  * @selector .slds-tile__meta
  * @restrict .slds-tile div
  */
.slds-tile__meta {
  color: var(--slds-g-color-neutral-base-10, #{$color-text-default});
}

.slds-tile_board,
.slds-tile--board {
  position: relative;

  .slds-has-alert {
    padding-right: $spacing-large;
  }
}

.slds-tile_board__icon,
.slds-tile--board__icon {
  @include square($square-icon-medium-content);
  position: absolute;
  bottom: $spacing-xx-small;
  right: $spacing-xx-small;
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

/**
 * @summary Initializes tile board
 *
 * @name tile-board
 * @selector .slds-tile_board
 * @restrict article
 * @support dev-ready
 * @variant
*/

.slds-tile_board,
.slds-tile--board {
  position: relative;

  .slds-has-alert {
    padding-right: $spacing-large;
  }
}

/**
  * @summary Tile board icon
  * @selector .slds-tile_board__icon
  * @restrict .slds-tile_board span
*/
.slds-tile_board__icon,
.slds-tile--board__icon {
  @include square($square-icon-medium-content);
  position: absolute;
  bottom: $spacing-xx-small;
  right: $spacing-xx-small;
}
